def coord_check(make_model, widths, batch, steps=3):
    rows = []
    for w in widths:
        model, opt = make_model(w)
        for t in range(steps + 1):
            h2 = hidden_preact(model, batch)
            rows.append((w, t, h2.abs().mean()))
            if t < steps:
                loss = loss_fn(model, batch)
                loss.backward()
                opt.step(); opt.zero_grad()
    return rows
